/// Refreshes the standard project-local Rust host and generated module index.
///
/// Existing project-authored Rust sources and current host files are preserved;
/// this only applies the same non-destructive host initialization used by new
/// project scaffolding.
///
/// # Errors
///
/// Returns project compatibility errors or a scaffold error when the current
/// Project Rust host cannot be refreshed.
pub fn refresh_project_game_host(path: &Path) -> Result<(), LifecycleError> {
    let project = inspect_project(path)?;
    initialize_game_project(&project).map_err(|error| LifecycleError::Scaffold {
        step: "game_project",
        message: error.to_string(),
    })
}

